// Checks the request of the lake API spike (GET with ?path=...).
// In: msg.req.query.path = a .parquet file in the lake, query.format.
// Out 1: msg.path and msg.format for the read node. Out 2: an error answer.
var DEFAULT_FORMAT = 'bytes';
var ALLOWED_FORMATS = [
  'bytes',
  'base64'
];
var REQUIRED_ENDING = '.parquet';

var query = (msg.req && msg.req.query) || {};
var path = String(query.path || '');
var format = String(query.format || DEFAULT_FORMAT);

var problem = '';
if (!path) {
  problem = 'query parameter path is missing';
} else if (path.slice(-REQUIRED_ENDING.length) !== REQUIRED_ENDING) {
  problem = 'only ' + REQUIRED_ENDING + ' files can be requested';
} else if (path.indexOf('..') !== -1 || path.indexOf('\\') !== -1) {
  problem = 'the path must not contain .. or a backslash';
} else if (path.charAt(0) === '/') {
  problem = 'the path must not start with /';
} else if (ALLOWED_FORMATS.indexOf(format) === -1) {
  problem = 'format must be one of: ' + ALLOWED_FORMATS.join(', ');
}

if (problem) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: problem
  });
  msg.statusCode = 400;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: problem
  };
  return [null, msg];
}

node.status({
  fill: 'green',
  shape: 'dot',
  text: format + ' ' + path
});
msg.path = path;
msg.format = format;
return [msg, null];

// Turns the read result into the HTTP answer of the lake API spike.
// In: msg.payload = file content (Buffer or serialised Buffer), msg.format.
// Out: bytes = the file itself, base64 = JSON with the file as text.
// Header x-parquet-magic tells if the first 4 bytes are PAR1.
var MAGIC = 'PAR1';

var content = msg.payload;
var bytes = null;
if (Buffer.isBuffer(content)) {
  bytes = content;
} else if (content && content.type === 'Buffer' && content.data) {
  bytes = Buffer.from(content.data);
}
if (!bytes) {
  node.error('the read node did not give bytes: ' + typeof content, msg);
  msg.statusCode = 500;
  msg.headers = {
    'content-type': 'application/json'
  };
  msg.payload = {
    error: 'the read node did not give bytes'
  };
  return msg;
}

var magic = bytes.slice(0, 4).toString('latin1') === MAGIC;
var name = String(msg.path).split('/').pop();
node.status({
  fill: magic ? 'green' : 'red',
  shape: 'dot',
  text: msg.format + ' ' + bytes.length + ' bytes'
});

msg.statusCode = 200;
msg.headers = {
  'x-parquet-magic': magic ? 'ok' : 'bad',
  'x-file-size': String(bytes.length)
};
if (msg.format === 'base64') {
  msg.headers['content-type'] = 'application/json';
  msg.payload = {
    path: msg.path,
    size: bytes.length,
    magic: magic,
    data: bytes.toString('base64')
  };
  return msg;
}

msg.headers['content-type'] = 'application/octet-stream';
msg.headers['content-disposition'] = 'attachment; filename="' + name + '"';
msg.payload = bytes;
return msg;

// Sets the folder to list for the list objects test.
// In: msg.payload = JSON {"path": "<folder or file in the lake>"}.
// Out: msg.path for the list objects node. Read the result in the debug.
var path = msg.payload && msg.payload.path;
if (!path) {
  node.error('payload needs a path, e.g. {"path":"reports/fact_kpi"}', msg);
  return null;
}
msg.path = path;
return msg;
